    description: "プリアンプは、次の機器が扱いやすい大きさまで、音を最初の段階で増幅する装置です。マイク用ならマイクプリ、ギター用ならギターのプリアンプ、と呼ばれます。名前は同じでも、つなぎ方と用途は別物です。\n\n使うと、小さな信号が大きくなり、録音やアンプへ送りやすくなります。ボーカルを録音するときは、マイク → マイクプリ（多くの場合はオーディオインターフェース内蔵）→ パソコン、という流れです。アコギをアンプやレコーダーへ送るときは、ギター用プリアンプが音を整え、送りやすくします。\n\nDTMの録音話で「プリ」と言ったら、だいたいマイクプリです。ギター雑誌の「プリアンプ」は、エフェクターやアコギ用の箱を指すことが多いです。混ぜると、買うものもつなぎ方もずれます。\n\n宅録では、マイク用はオーディオインターフェースに内蔵されていることが多く、ギター用はエフェクターや専用プリアンプとして単体になることもあります。マイク録音だけなら、別途プリアンプを買う必要は通常ありません。\n\n我が家では MOTU M2 と Steinberg UR242 にマイク用のプリアンプ（マイクプリ）が入っています。ギター／アコギ用としては BOSS AD-8 と BOSS MOBILE AC にプリアンプ機能が登録されています。AMS Neve 1073N は購入検討の登録です。",
