    description: "A/D変換（アナログ→デジタル）は、マイクや楽器のアナログ音声を、パソコンで扱えるデジタルデータへ変えることです。録音するときの向きです。空気の振動をマイクが電気に変え、マイクプリで大きくしたあと、この変換で数字の列になります。\n\nマイク → マイクプリで増幅 → A/D変換 → Cubase や Logic、という流れです。ボーカルを録音するとき、IFのGAINを回したあとパソコンに入る直前の仕事がこれです。逆方向の D/A変換は、パソコンの音をスピーカーやヘッドホンで鳴らせるアナログ信号に戻すことで、再生するときの向きです。入るときがA/D、出るときがD/A、と覚えると混同しにくいです。\n\nこの変換は、普通はオーディオインターフェースの中で行われます。単体のADコンバーターを買っていなくても、MOTU M2 や Steinberg UR242 で録音できているのは、内蔵A/Dがあるからです。高級IFでは、この変換の品質が価格差の一因になることがあります。宅録ではIF内蔵で足りることがほとんどです。歌1本・ギター1本なら、単体のADを足す話にはなりにくいです。",
