    description: "ルーティングは、「どの音を、どこへ送るか」を決めることです。マイクをどの入力へ入れるか、DAWのどのトラックに録るか、歌手のヘッドホンに何を聴かせるか、スピーカーへ何を出すか、全部ルーティングです。配線図の話でもあり、画面上の送り先の話でもあります。\n\n例えば、トークバック（録音担当の声）だけを歌手のヘッドホンへ送り、スピーカーには出さない、というのが典型です。伴奏は大きく、自分の声はもっと大きく、クリックは歌手にだけ、といった分け方もルーティングです。Cubase でトラックの入力に「入力1」を選ぶ、出力をステレオアウトにする、センドでリバーブへ送る、も毎日のルーティングです。\n\nオーディオインターフェースの入力選択、DAWの入出力設定、センド／バス、RME の TotalMix FX、Apollo の UAD Console などで、この言葉がよく出ます。宅録でも、入力を選んだ時点で必ず行っています。大きなスタジオではパッチベイやコンソールで複雑に組むことがあります。\n\nPC＋インターフェース1台の普通の宅録では、DAWの入出力設定が中心です。名前を知らなくても毎日使っている基本用語です。特別な機材を買う話ではありません。",
