    description: "ダッキングは、ある音が鳴った瞬間に、別の音を自動的に小さくする処理です。起こる動作の名前です。主役の音が通るあいだ、脇役を一歩下がらせる、イメージです。\n\n分かりやすい例は、ナレーションが入った瞬間にBGMが自動的に下がることです。音楽では、キックが鳴った瞬間にベースを下げる、ボーカルが歌っているあいだパッドを下げる、といった使い方もあります。下がると、主役の音が聴こえやすくなります。Cubase や Logic のコンプで作ることが多いです。\n\nこの動きを作る仕組みのひとつがサイドチェインです。ダッキング＝起こる動作、サイドチェイン＝その動作を作るために使われる仕組みの一つ、と覚えると混同しにくいです。サイドチェイン以外でも、オートメーションで同じ動きを書くことはできます。\n\n宅録でも、ナレーション動画やキックとベースの整理でよく出る言葉です。特別な機材は不要です。かけすぎると、脇役がペコペコ動いて不自然になります。",
